import { useEffect } from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { useAuthStore } from "@/stores/auth";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";

import Landing from "@/pages/Landing";
import Login from "@/pages/Login";
import Register from "@/pages/Register";
import Cabinet from "@/pages/Cabinet";
import Quiz from "@/pages/Quiz";
import Contact from "@/pages/Contact";
import About from "@/pages/About";
import ForTeachers from "@/pages/ForTeachers";
import ForSchoolChildren from "@/pages/ForSchoolChildren";
import ForParents from "@/pages/ForParents";
import ForStudents from "@/pages/ForStudents";
import ForLibrary from "@/pages/ForLibrary";
import ForResearchers from "@/pages/ForResearchers";

function ProtectedRoute({ children }: { children: JSX.Element }) {
  const { user } = useAuthStore();
  if (!user) return <Navigate to="/login" replace />;
  return children;
}

function AuthRoute({ children }: { children: JSX.Element }) {
  const { user } = useAuthStore();
  if (user) return <Navigate to="/" replace />;
  return children;
}

export default function App() {
  const { initialize } = useAuthStore();

  useEffect(() => {
    initialize();
  }, [initialize]);

  return (
    <TooltipProvider>
      <Toaster />
      <div className="min-h-screen bg-white">
        <Navbar />
        <main>
          <Routes>
            <Route path="/" element={<Landing />} />

            <Route
              path="/login"
              element={
                <AuthRoute>
                  <Login />
                </AuthRoute>
              }
            />
            <Route
              path="/register"
              element={
                <AuthRoute>
                  <Register />
                </AuthRoute>
              }
            />

            <Route
              path="/cabinet"
              element={
                <ProtectedRoute>
                  <Cabinet />
                </ProtectedRoute>
              }
            />

            <Route
              path="/test"
              element={
                <ProtectedRoute>
                  <Quiz />
                </ProtectedRoute>
              }
            />

            {/* ✅ NEW: direct test by ID */}
            <Route
              path="/test/:id"
              element={
                <ProtectedRoute>
                  <Quiz />
                </ProtectedRoute>
              }
            />

            <Route path="/contact" element={<Contact />} />
            <Route path="/about" element={<About />} />

            <Route path="/for-teachers" element={<ForTeachers />} />
            <Route path="/for-school-children" element={<ForSchoolChildren />} />
            <Route path="/for-parents" element={<ForParents />} />
            <Route path="/for-students" element={<ForStudents />} />
            <Route path="/for-library" element={<ForLibrary />} />
            <Route path="/for-researchers" element={<ForResearchers />} />

            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </TooltipProvider>
  );
}
